function replace(text,hook,undo){const {before,after,scope}=hook,from=undo?after:before,to=undo?before:after;const start=scope?text.indexOf(scope[0]):0,end=scope?text.indexOf(scope[1],start):text.length;if(start<0||end<start)throw Error('Missing hook scope');let part=text.slice(start,end);if(!undo&&part.includes(after))return text;if(part.split(from).length!==2)throw Error('Ambiguous visualization hook: '+from.slice(0,80));part=part.replace(from,to);return text.slice(0,start)+part+text.slice(end);}
function apply(text){for(const hook of hooks)text=replace(text,hook,false);return text;}
function revert(text){for(const hook of [...hooks].reverse())text=replace(text,hook,true);return text;}
module.exports={hooks,apply,revert};
